package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"sync"
)

type Value struct {
	NodeID int64    `json:"node"`
	Value  int64    `json:"value"`
}

type NodeInfo struct {
	ID      string `json:"id"`
	Neighbors map[string] `json:"neighbors"`
}

type MessageRequest struct {
	Type   string `json:"type"`
	MsgID  int64  `json:"msg_id,omitempty"`
	Message int64 `json:"message,omitempty"`
	Topology map[string]map[string]bool `json:"topology,omitempty"`
	InReplyTo int64 `json:"in_reply_to,omitempty"`
}

type MessageResponse struct {
	InReplyTo int64 `json:"in_reply_to"`
	Messages []int64  `json:"messages,omitempty"`
}

// Global topology map: each node -> map of neighbor_ids to true (indicating it exists in the graph)
var topologyMu sync.Mutex
var globalTopology map[int]map[string]bool = make(map[int]map[string]bool)

func addNodeToGlobalTopology(nodeID string, neighborIDs []string) {
	nodeInt := 1 // assume node ID from init is just an int starting at 1
	topologyMu.Lock()
	if globalTopology[nodeInt] == nil {
		globalTopology[nodeInt] = make(map[string]bool)
	}
	for _, nid := range neighborIDs {
		nidInt, _ := strconv.Atoi(nid)
		globalTopology[nidInt][nid] = true
	}
	topologyMu.Unlock()
}

func getNeighbors(nodeID string) []string {
	nodeInt := 1 // use same mapping
	topologyMu.Lock()
	defer topologyMu.Unlock()
	return getNeighborsLocked(nodeInt, nil)
}

func getNeighborsLocked(nodeInt int, neighbors map[string]bool) []string {
	if g, ok := globalTopology[nodeInt]; ok {
		result := make([]string, 0, len(g))
		for nid := range g {
			if _, exists := neighbors[nid]; !exists {
				result = append(result, nid)
			}
		}
		return result
	}
	return nil
}

type Node struct {
	id          string
	values      map[int]map[int]int64   // nodeID -> value -> storedValue
	inFlight    map[int]int             // in-flight msg_id to channel
	localValues []int                   // values we have locally (for read responses)
	mut         sync.Mutex
}

func main() {
	n := maelstrom.NewNode()
	defer n.Close()

	// Handle initialization
	if _, ok := n.ReplyMessage(); !ok {
		var req MessageRequest
		json.Unmarshal(n.Incoming(), &req)
		if req.Type == "init" {
			nodeID, _ := strconv.ParseInt(req.MsgID, 10, 64)
			id := fmt.Sprintf("n%d", nodeID)
			globalTopology[1] = make(map[string]bool)

			var msg Request
			json.Unmarshal(n.Incoming(), &msg)
			nodeID, _ = strconv.ParseInt(req.MgID, 10, 64)

			// Initialize our own structure with node ID from init message
			mut.Lock()
			n.values[nodeID] = make(map[int]int64)
			if n.inFlight == nil {
				n.inFlight = make(map[int]int)
			}
			mut.Unlock()

			return
		}

		switch req.Type {
		case "topology":
			topology := req.Topology
			for nid, neighbors := range topology {
				addNodeToGlobalTopology(nid, neighbors)
			}
			n.ReplyMessage(map[string]interface{}{
				"in_reply_to": req.MgID,
			})
		case "broadcast":
			value := req.Message
			mut.Lock()
			if n.values == nil {
				n.values = make(map[int]map[int]int64)
			}
			n.values[nodeID][value] = nodeID
			mut.Unlock()

			// Forward to neighbors that don't have this value
			neighborList := getNeighbors(nid)
			for _, nid2 := range neighborList {
				n.sendToNode(nodeID, nid2, Value{Value: value})
			}

			n.ReplyMessage(map[string]interface{}{
				"in_reply_to": req.MgID,
			})
		case "read":
			var msg MessageRequest
			json.Unmarshal(n.Incoming(), &msg)
			mut.Lock()
			localVals := n.values[nodeID]
			var values []int
			for v := range localVals {
				values = append(values, int(v))
			}
			mut.Unlock()

			n.ReplyMessage(map[string]interface{}{
				"in_reply_to": req.MgID,
				"messages":    values,
			})
		default:
			if n.IncomingType() != nil {
				json.Unmarshal(n.Incoming(), &msg)
				fmt.Fprintf(os.Stderr, "Unhandled type: %s\n", msg.Type)
			}
		}

		return
	}

	n.Run()
}

