var globalTopology = make(map[int][]int)
var topologyMu sync.RWMutex

// Per-node state
type NodeState struct {
	values      map[int]int64    // msg_id -> value (if we broadcast it here)
	inFlight    map[int]struct{} // msg_ids that have been acknowledged
	nextMsgID   int64
	mut         sync.Mutex
