func newNodeState() *NodeState {
	return &NodeState{
		values:     make(map[int]int64),
		inFlight:   make(map[int]struct{}),
		nextMsgID:  0,
	}
}

func main() {
	if err := maelstrom.Run(maelstrom.NodeConfig{}, func(n *maelstrom.Node) {

		var msg interface{}
		json.Unmarshal(n.Incoming(), &msg)

		switch m := msg.(type) {
		case map[string]interface{}:
			// Handle initialization message
			nodeIDStr := m["id"].(string)
			idInt, _ := strconv.ParseInt(nodeIDStr, 10, 64)

			// Parse global topology from init message if present
			if gTopo, ok := m["globalTopology"]; ok {
