					for _, nidStr2 := range tm.([]string) {
						nidInt, _ := strconv.ParseInt(nidStr2, 10, 64)
						neighborIDs = append(neighborIDs, int(nidInt))
					}
					globalTopology[int(nidInt)] = neighborIDs
				}
			}

			var req MessageRequest
			json.Unmarshal([]byte(m["type"].(string)), &req)

			switch req.Type {
			case "init":
				nodeID, _ := strconv.ParseInt(req.MgID, 10, 64)
				state := newNodeState()
				n.StoreState(nodeID, state)

				// Set up topology map from globalTopology
				var neighbors []int
				for nidStr := range m {
					if nidStr == "id" {
						continue
					}
					var nbIDs []int
					tm := m[nidStr].([]string)
					for _, nidStr2 := range tm {
						nidInt, _ := strconv.ParseInt(nidStr2, 10, 64)
						nbIDs = append(nbIDs, int(nidInt))
					}
					neighbors = append(neighbors, nbIDs...)
				}

			case "topology":
				topology := req.Topology
				for nidStr, neighborsJSON := range topology {
					var neighborIDs []int
					tm := neighborsJSON.(map[string]struct{})
					for nidStr2 := range tm {
						nidInt, _ := strconv.ParseInt(nidStr2, 10, 64)
						neighborIDs = append(neighborIDs, int(nidInt))
					}
					globalTopology[int(nidInt)] = neighborIDs
				}

			case "broadcast":
				value := req.Message
				mut.Lock()
				if n.state.values == nil {
					n.state.values = make(map[int]int64)
				}
				n.state.values[req.MsgID] = value
				mut.Unlock()

				// Forward broadcast to all nodes in topology
				for nidStr, neighbors := range globalTopology {
					// Forward from our node to each neighbor
					for _, nbID := range neighbors {
						n.Send(&Value{NodeID: int64(nbID), Value: value})
					}
				}

			case "read":
				var resp MessageResponse
				mut.Lock()
				if n.state.values != nil {
					resp.Messages = make([]int, 0)
					for msg := range n.state.values {
						resp.Messages = append(resp.Messages, int(msg))
					}
				}
				mut.Unlock()

			case "broadcast_ok":
				mut.Lock()
				n.state.inFlight[req.InReplyTo] = struct{}{}
				mut.Unlock()

			default:
				return
			}

			json, _ := json.Marshal(map[string]interface{}{
				"in_reply_to": req.MgID,
			})
			n.Send(json)

		case Value:
			// Received a value broadcast from another node
			valueNodeID := m.NodeID
			value := int64(m.Value)
			mut.Lock()
			if n.state.values == nil {
				n.state.values = make(map[int]int64)
			}
			n.state.values[req.MsgID] = value
			mut.Unlock()

		default:
			log.Printf("Unhandled message type: %v", msg)
			return
		}

		var resp interface{}
		if req.Type == "topology" {
			resp = map[string]interface{}{
				"in_reply_to": m.MgID,
			}
		} else if req.Type == "broadcast" {
			resp = map[string]interface{}{
				"in_reply_to": m.MsgID,
			}
		} else {
			return // don't reply for other types
		}

		json, _ := json.Marshal(resp)
		n.Send(json)

	}, n.ID())
}

package main

import (
	"encoding/json"
	"log"
	"os"
	"sync"

	"github.com/jepsen-io/maelstrom/demo/go"
)

type Value struct {
	NodeID int64 `json:"node"`
	Value  int64 `json:"value"`
}

// Global topology for all nodes in the cluster
var globalTopology = make(map[int][]int)
var topoMu sync.RWMutex

// Per-node state
type NodeState struct {
	values     map[int]map[int]int64 // msg_id -> value -> stored_value (value we received/created here)
	inFlight   map[int]struct{}      // in-flight broadcasts from clients
	nextMsgID  int64
	mut        sync.Mutex
}

func newNodeState() *NodeState {
	return &NodeState{
		values:     make(map[int]map[int]int64),
		inFlight:   make(map[int]struct{}),
		nextMsgID:  0,
	}
}

// Store state for a specific node ID
func (ns *NodeState) GetState(nodeId int) map[int]map[int]int64 {
	mut.Lock()
	defer mut.Unlock()
	if nodeId != -1 && ns.values[nodeId] != nil {
		return ns.values[nodeId]
	}
	return nil
}

// Initialize a node's state
func (ns *NodeState) Init(id int, topo []int) {
	mut.Lock()
	defer mut.Unlock()
	if id == -1 {
		ns.values[id] = make(map[int]map[int]int64)
		for _, nbId := range topo {
			ns.values[nbId] = make(map[int]map[int]int64)
		}
		return
	}
	ns.values[id] = make(map[int]map[int]int64)
	if len(topo) > 0 {
		for _, nbId := range topo {
			ns.values[nbId] = make(map[int]map[int]int64)
		}
		return
	}
}

func main() {
	// Handle initialization message from maelstrom
	var msg interface{}
	if err := json.Unmarshal(maelstrom.Incoming(), &msg); err != nil {
		log.Fatalf("Error reading incoming: %v", err)
	}

	m, ok := msg.(map[string]interface{})
	if !ok {
		log.Printf("Unknown init message format: %v", msg)
		os.Exit(1)
	}

	// Parse node ID and topology from init
	nodeIDStr := m["id"].(string)
	idInt, _ := strconv.ParseInt(nodeIDStr, 10, 64)
	state := newNodeState()
	maelstrom.StoreState(idInt, state)

	// Initialize our state
	ns := maelstrom.GetState(idInt)
	topo, ok := m["topology"].([]string)
	if !ok {
		ns = make(map[int]map[int]int64)
	}

	// Setup topology map
	for _, tNodeIDStr := range topo {
		tNodeID, _ := strconv.ParseInt(tNodeIDStr, 10, 64)
		ns[tNodeID] = make(map[int]map[int]int64)
	}

	maelstrom.GetState(idInt)

	mut.Lock()
	ns = maelstrom.GetState(idInt)
	ns[idInt] = make(map[int]map[int]int64)
	mut.Unlock()

	for i, tNodeIDStr := range topo {
		tNodeID, _ := strconv.ParseInt(tNodeIDStr, 10, 64)
		ns[tNodeID] = make(map[int]map[int]int64)
	}

	var req MessageRequest
	json.Unmarshal(maelstrom.Incoming(), &req)

	switch req.Type {
	case "topology":
		topologyJSON := req.Topology
		for nidStr, neighbors := range topologyJSON {
			var nIDs []int
			for nIDStr := range neighbors {
				if ni, err := strconv.ParseInt(nIDStr, 10, 64); err == nil {
					nIDs = append(nIDs, int(ni))
				}
			}
			ns[int(nidStr)] = make(map[int]map[int]int64)
			for _, nID := range nIDs {
				ns[int(nidStr)][nID] = make(map[int]int64)
			}
		}

	case "broadcast":
		value := req.Message
		msgID := req.MsgID
		mut.Lock()
		ns[msgID] = make(map[int]int64)
		ns[msgID][idInt] = value
		mut.Unlock()

		// Find and broadcast to nodes that don't have this value yet
		for nidStr, neighbors := range ns {
			hasValue := false
			if values, ok := neighbors[msgID]; ok {
				if _, ok := values[idInt]; ok {
					hasValue = true
				}
			}

			if !hasValue {
				var neighborIDs []int
				for nIDStr := range ns[int(nidStr)] {
					if _, hasNID := ns[int(nidStr)][nIDStr]; hasNID {
						neighborIDs = append(neighborIDs, int(nIDStr))
					}
				}

				for _, nID := range neighborIDs {
					valMap := neighbors[nID]
					if valMap == nil || valMap[msgID] == nil {
						var msgToForward Value
						msgToForward.NodeID = idInt
						msgToForward.Value = value
						maelstrom.Send(nID, &msgToForward)
					}
				}
			}

			mut.Unlock()
		}

	case "read":
		var resp MessageResponse
		mut.Lock()
		if ns != nil {
			resp.Messages = make([]int, 0)
			for msgID := range ns[idInt] {
				resp.Messages = append(resp.Messages, msgID)
			}
		}
		mut.Unlock()

	case "broadcast_ok":
		inReplyTo := req.InReplyTo
		mut.Lock()
		ns[idInt][inReplyTo] = map[int]int64{idInt: value}
		if ns[inReplyTo] == nil {
			ns[inReplyTo] = make(map[int]int64)
		}
		ns[inReplyTo][idInt] = value
		mut.Unlock()

	case "init":
	default:
		return
	}

	var resp interface{}
	if req.Type == "topology" {
		resp = map[string]interface{}{"in_reply_to": req.MgID}
	} else if req.Type == "broadcast" || req.Type == "broadcast_ok" {
		resp = map[string]interface{}{"in_reply_to": msgID}
	}

	jsonResp, _ := json.Marshal(resp)
	maelstrom.Send(jsonResp)
}

