		log.Fatalf("Failed to parse init message: %v", err)
	}

	initMap, ok := initMsg.(map[string]interface{})
	if !ok {
		log.Printf("Unknown init message format")
		os.Exit(1)
	}

	// Parse node ID from init message
	nodeIDStr := initMap["id"].(string)
	idInt, _ := strconv.ParseInt(nodeIDStr, 10, 64)

	// Setup global topology from init if provided
	for nidStr, neighbors := range initMap {
		if nidStr == "id" {
			continue
		}
		neighborIDs := make([]int, 0)
		if neighborSlice, ok := neighbors.([]string); ok {
			for _, nStr := range neighborSlice {
				nIDInt, _ := strconv.ParseInt(nStr, 10, 64)
				neighborIDs = append(neighborIDs, int(nIDInt))
			}
		}
		globalTopology[int(nidStr)] = neighborIDs
	}

	var req MessageRequest
	json.Unmarshal(maelstrom.Incoming(), &req)

	switch req.Type {
	case "topology":
		topoJSON := req.Topology
		for nidStr, neighbors := range topoJSON {
			if _, ok := neighbors["self"]; ok {
				continue // skip self in global topology setup
			}
			var nIDs []int
			for nStr := range neighbors {
				nIDInt, _ := strconv.ParseInt(nStr, 10, 64)
				nIDs = append(nIDs, int(nIDInt))
			}
			globalTopology[int(nidStr)] = nIDs
		}
		resp := map[string]interface{}{"in_reply_to": req.MgID}

	case "broadcast":
		value := req.Message
		msgID := req.MsgID
		resp := map[string]interface{}{"in_reply_to": msgID}

		mut.Lock()
		localValues[req.MsgID] = value

		// Forward to neighbors
		topologyMu.Lock()
		neighbors := globalTopology[int(idInt)]
		topologyMu.Unlock()

		for _, nID := range neighbors {
			valMap := localValues[nID]
			if valMap == nil || valMap[msgID] == 0 {
				var fwd Value
				fwd.NodeID = int64(nID)
				fwd.Value = value
				maelstrom.Send(nID, &fwd)
			}
		}
		mut.Unlock()

	case "read":
		resp := map[string]interface{}{
			"in_reply_to": msgID,
		}

	case "broadcast_ok":
		inReplyTo := req.InReplyTo
		resp := map[string]interface{}{"in_reply_to": inReplyTo}

	default:
		return
	}

	jsonResp, _ := json.Marshal(resp)
	maelstrom.Send(jsonResp)
}

